import { Component, Input } from '@angular/core';
import { PerfilUsuario } from '../../../../models/perfil.usuario';
import { PerfilUsuarioService } from '../../../../controllers/perfil.usuario.service';
import { RecordFormComponent } from '../../../../shared/record-form/record-form.component';
import { RecordFormButtonsComponent } from '../../../../shared/record-form/record-form-buttons/record-form-buttons.component';

import { AutocompleteFieldComponent } from '../../../../shared/generic-form/autocomplete-field/autocomplete-field.component';
import { PermisoUsuarioComponent } from '../permiso-usuario/permiso-usuario.component';
import { UtilsService } from '../../../../services/utils.service';
import { TipoUsuario } from '../../../../models/tipo.usuario.model';
import { TipoUsuarioService } from '../../../../controllers/tipo.usuario.service';
import { PermisoUsuario } from '../../../../models/permiso.usuario';
import { PermisoUsuarioService } from '../../../../controllers/permiso.usuario.service';
import { PermisoService } from '../../../../controllers/permiso.service';
import { SucursalService } from '../../../../controllers/sucursal.service';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';

@Component({
  selector: 'app-perfil-usuario',
  imports: [
    RecordFormButtonsComponent,
    AutocompleteFieldComponent,
    PermisoUsuarioComponent,
  ],
  templateUrl: './perfil-usuario.component.html',
  styleUrl: './perfil-usuario.component.css',
})
export class PerfilUsuarioComponent extends RecordFormComponent<PerfilUsuario> {
  showPermisos = false;

  idNuevoPermiso: number | undefined;

  filtrosPermisos: any = {};

  filtrosTiposUsuarios: any = {};

  constructor(
    public perfilController: PerfilUsuarioService,
    public tipoUsuarioController: TipoUsuarioService,
    private permisoUsuarioController: PermisoUsuarioService,
    public utils: UtilsService,
    private sucursalController: SucursalService,
    private permisoController: PermisoService,
    private storage: LocalStorageService,
  ) {
    super(perfilController);
  }

  override ngOnInit() {
    if (!this.record.id) {
      this.edit = true;
    }
    this.setFiltroTiposUsuarios();
    this.updateFiltros();
  }

  private setFiltroTiposUsuarios() {
    const login = this.storage.getPerfil();

    console.log('login', login);

    this.filtrosTiposUsuarios = {
      conditionals: JSON.stringify([
        ['rango', '<=', login.tipos_usuarios.rango],
      ]),
    };
  }

  private updateFiltros() {
    const omitidosCondicionales = this.permisosOmitidos();
    this.filtrosPermisos = {
      conditionals: JSON.stringify([
        ['rango', '>=', this.record.tipos_usuarios?.rango],
        ['deleted_at', 'IS NULL', null],
        ...omitidosCondicionales,
      ]),
    };
  }

  permisosOmitidos() {
    const list: any[][] = [];
    if (!this.record.permisos_usuarios) return [];
    this.record.permisos_usuarios.forEach((permiso) => {
      list.push(['id', '!=', permiso.permiso_id]);
    });
    return list;
  }

  protected override async afterSaved(): Promise<void> {
    this.record.tipos_usuarios = await this.tipoUsuarioController.find(
      this.record.tipos_usuario_id,
    );
    this.record.sucursales = await this.sucursalController.find(
      this.record.sucursal_id,
    );
    this.record.permisos_usuarios = [];
    this.updateFiltros();
  }

  public async onPermisoSelected() {
    if (!this.record.permisos_usuarios) this.record.permisos_usuarios = [];
    console.log(this.idNuevoPermiso);

    if (this.idNuevoPermiso) {
      const res = await this.permisoUsuarioController.createOrRestore({
        perfiles_usuario_id: this.record.id,
        permiso_id: this.idNuevoPermiso,
      });
      if (res) {
        res.permisos = await this.permisoController.find(res.permiso_id);
        this.record.permisos_usuarios.push(res);
        this.idNuevoPermiso = undefined;
      }
    }
  }

  public async agregarTodosPermisos() {
    const permisos = await this.permisoController.all([
      {
        key: 'deleted_at',
        operator: 'IS NULL',
        value: null,
      },
      {
        key: 'rango',
        operator: '>=',
        value: this.record.tipos_usuarios?.rango ?? 0,
      },
    ]);
    if (!this.record.permisos_usuarios) this.record.permisos_usuarios = [];
    for (const permiso of permisos) {
      const res = await this.permisoUsuarioController.createOrRestore(
        {
          perfiles_usuario_id: this.record.id,
          permiso_id: permiso.id,
        },
        false,
      );
      if (res) {
        res.permisos = permiso;
        if (!this.record.permisos_usuarios.find((per) => per.id == res.id)) {
          this.record.permisos_usuarios.push(res);
        }
      }
    }
  }

  public onPermisoDeleted(permiso: PermisoUsuario) {
    this.utils.localDelete(this.record.permisos_usuarios, permiso);
    this.updateFiltros();
  }
}
