import { Component } from '@angular/core';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { Usuario } from '../../../models/usuario.model';
import { UsuarioService } from '../../../controllers/usuario.service';
import { ActivatedRoute } from '@angular/router';

import { PerfilUsuarioComponent } from "./perfil-usuario/perfil-usuario.component";
import { UtilsService } from '../../../services/utils.service';

const FORMDEF: Form = [
  {
    title: 'Datos del usuario',
    fields: [
      {
        type: 'email',
        label: 'Correo electronico',
        key: 'email',
        validator: {
          required: true,
          email: true
        }
      },
      {
        type: 'text',
        label: 'Contraseña',
        key: 'password',
      },
      {
        type: 'text',
        label: 'Nombre',
        key: 'nombre',
        validator: {
          required: true
        }
      },
      {
        type: 'text',
        label: 'Apellido Paterno',
        key: 'apellido_paterno',
        validator: {
          required: true
        }
      },
      {
        type: 'text',
        label: 'Apellido Materno',
        key: 'apellido_materno',
        style: {
          div: 'col p-3'
        },
        validator: {
          required: true
        }
      },
    ]
  },
]

@Component({
    selector: 'app-usuario-form',
    imports: [
    GenericFormComponent,
    PerfilUsuarioComponent
],
    templateUrl: './usuario-form.component.html',
    styleUrl: './usuario-form.component.css'
})
export class UsuarioFormComponent {
  form: Form = FORMDEF
  edit?: Usuario

  sections :{ [key:string]:boolean; } = {
    datos: true,
    perfiles: false,
  }

  constructor(
    public usuarioController: UsuarioService,
    private route: ActivatedRoute,
    public utils:UtilsService,
  ) { }

  ngOnInit() {
    this.route.params.subscribe(async (params) => {
      if (params['usuario_id']) {
        this.edit = await this.usuarioController.find(params['usuario_id'],['perfilesUsuarios.permisosUsuarios.permisos', 'perfilesUsuarios.tiposUsuarios', 'perfilesUsuarios.sucursales'])
        this.edit?.perfiles_usuarios?.sort((a,b)=>{
          return (a.tipos_usuarios?.rango??0) - (b.tipos_usuarios?.rango??0)
        })
        console.log(this.edit)
      }
    })
  }

  onTabSelected(key:string){
    for(const key of Object.keys(this.sections)){
      this.sections[key]=false
    }
    this.sections[key]=true
  }

  nuevoPerfil(){
    if(!this.edit) return
    if(!this.edit.perfiles_usuarios) this.edit.perfiles_usuarios=[]
    this.edit.perfiles_usuarios.push({
      usuario_id: this.edit.id,
      tipos_usuario_id: 0,
      sucursal_id: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
  }
}
